const assert = require('node:assert/strict');
const http = require('node:http');
const path = require('node:path');
const dependencyRoot = process.argv[2];
const stage = process.argv[3];
const proxyaddr = require(path.join(dependencyRoot, 'proxy-addr'));
const version = require(path.join(dependencyRoot, 'proxy-addr/package.json')).version;
const spoofed = '203.0.113.77';
const trust = proxyaddr.compile(['::ffff:10.0.0.0/8']);
const server = http.createServer((request, response) => {
  response.setHeader('content-type', 'application/json');
  response.end(JSON.stringify({ peer: request.socket.remoteAddress, resolved: proxyaddr(request, trust) }));
});
(async () => {
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  try {
    const address = server.address();
    assert.equal(typeof address, 'object');
    const result = await fetch(`http://127.0.0.1:${address.port}/`, { headers: { 'x-forwarded-for': spoofed } });
    const receipt = await result.json();
    assert.equal(receipt.peer, '127.0.0.1');
    console.log(JSON.stringify({ stage, version, ...receipt, vulnerabilityObserved: receipt.resolved === spoofed,
      localHttpRequests: 1, externalModelCalls: 0, jevCalls: 0 }));
    assert.equal(version, stage === 'red-before' ? '2.0.7' : '2.0.8');
    assert.equal(receipt.resolved, receipt.peer, 'untrusted local client must not supply the resolved IP');
  } finally {
    await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
  }
})().catch(error => { console.error(error.message); process.exitCode = 1; });
